import { useRef, useState } from "react";
import { ImageIcon, Upload } from "lucide-react";
import useVantaHalo from "./useVantaHalo";

async function sendToResumeAnalysisAgent(file) {
  console.log("Sending to resume analysis agent:", file.name);
}

export default function Home({ setPage }) {
  const vantaRef = useVantaHalo();
  const fileInputRef = useRef(null);
  const [status, setStatus] = useState("idle");

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.type !== "application/pdf") {
      setStatus("error");
      return;
    }

    setStatus("sending");

    try {
      await sendToResumeAnalysisAgent(file);
      setPage("interview");
    } catch (err) {
      console.error(err);
      setStatus("error");
    } finally {
      e.target.value = "";
    }
  };

  return (
    <div ref={vantaRef} className="min-h-screen flex flex-col items-center justify-center px-6 py-16 text-center">
      <h1 className="text-3xl font-semibold text-white mb-3">Home</h1>
      <p className="text-white/70 leading-relaxed mb-10">
        This is the home page. Swap this content out for whatever your app
        needs to show first.
      </p>

      <div className="w-full max-w-sm aspect-square rounded-lg border border-dashed border-white/30 bg-white/10 flex items-center justify-center mb-6">
        <ImageIcon size={40} className="text-white/40" />
      </div>

      <button
        onClick={handleUploadClick}
        className="flex items-center gap-2 px-4 h-10 rounded-md text-sm font-medium bg-white text-stone-900 hover:bg-white/90 transition-colors"
      >
        <Upload size={16} />
        {status === "sending" ? "Sending…" : "Upload resume"}
      </button>

      <input
        ref={fileInputRef}
        type="file"
        accept="application/pdf"
        onChange={handleFileChange}
        style={{ display: "none" }}
      />

      {status === "error" && (
        <p className="text-sm text-red-400 mt-3">Please upload a PDF file.</p>
      )}
    </div>
  );
}
